const leads = $items("Get - Leads1", 0).map(i => i.json);
const configs = $items("Get row(s) in sheet1", 0).map(i => i.json);

function onlyDigits(value) {
  return String(value || "").replace(/\D/g, "");
}

function generatePhoneVariants(phone) {
  const digits = onlyDigits(phone);
  const variants = [digits];

  if (digits.startsWith("55") && digits.length === 13 && digits[4] === "9") {
    const withoutNine = digits.slice(0, 4) + digits.slice(5);
    if (!variants.includes(withoutNine)) {
      variants.push(withoutNine);
    }
  } else if (digits.startsWith("55") && digits.length === 12) {
    const withNine = digits.slice(0, 4) + "9" + digits.slice(4);
    if (!variants.includes(withNine)) {
      variants.push(withNine);
    }
  }

  return variants;
}

// pega só a primeira config
const config = configs[0] || {};

const tiposAtivos = [];
if (config["MASCULINA"] === true) tiposAtivos.push("MASCULINA");
if (config["FEMININA"] === true) tiposAtivos.push("FEMININA");

const result = [];

for (const lead of leads) {
  const phoneVariants = generatePhoneVariants(lead["TELEFONE"]);

  for (const tipo of tiposAtivos) {
    for (const telefone of phoneVariants) {
      result.push({
        json: {
          ...lead,
          "TELEFONE": telefone,
          "TIPO": tipo,
          "ID DA CAIXA": config["ID DA CAIXA"]
        }
      });
    }
  }
}

return result;

const seen = new Set();

function normalizePhone(value) {
  let id = String(value || "")
    .replace("@s.whatsapp.net", "")
    .replace("@c.us", "")
    .replace(/\D/g, "");

  // remove o 9 extra (BR) para deduplicação
  if (id.startsWith("55") && id.length === 13 && id[4] === "9") {
    id = id.slice(0, 4) + id.slice(5);
  }

  return id;
}

return $items()
  .map(i => i.json)
  .filter(i => i && i.data && i.data.wuid)
  .filter(i => {
    const id = normalizePhone(i.data.wuid);

    if (seen.has(id)) return false;
    seen.add(id);
    return true;
  })
  .map(i => {
    const data = i.data || {};

    const wuid = data.wuid ?? null;
    const numberExists = data.numberExists ?? null;

    const originalRaw = i.original_phone ?? null;
    const original_phone =
      originalRaw === null || originalRaw === undefined || String(originalRaw).trim() === ""
        ? null
        : String(originalRaw).replace(/\D/g, "");

    const rowRaw = i.row_number ?? null;
    const row_number =
      rowRaw === null || rowRaw === undefined || String(rowRaw).trim() === ""
        ? null
        : Number(rowRaw);

    const razao = i.razao ?? "";
    const cnpj = i.cnpj ?? "";
    const observacao = i.observacao ?? "";
    const tipo = i.TIPO ?? i.Tipo ?? i.tipo ?? null;
    const idDaCaixa = i["ID DA CAIXA"] ?? i.id_da_caixa ?? i.idDaCaixa ?? null;

    const quemRaw = i["QUEM?"] ?? i.QUEM ?? i.Quem ?? null;
    const quem =
      quemRaw === null || quemRaw === undefined || String(quemRaw).trim() === ""
        ? null
        : String(quemRaw).replace(/\D/g, "");

    return {
      json: {
        ...(wuid ? { wuid } : {}),
        ...(numberExists !== null ? { numberExists } : {}),
        ...(row_number !== null && !Number.isNaN(row_number) ? { row_number } : {}),
        ...(original_phone ? { original_phone } : {}),
        razao,
        cnpj: String(cnpj),
        observacao,
        ...(tipo !== null ? { TIPO: tipo } : {}),
        ...(idDaCaixa !== null ? { "ID DA CAIXA": idDaCaixa } : {}),
        ...(quem ? { "QUEM": quem } : {})
      }
    };
  });

